# Construct the output grid based on the pattern
def make_hollow_block(size, fill_color, border_color):
    """Create a hollow block with border color and interior fill color"""
    if size <= 2:
        # Too small to have hollow interior, just border
        return [[border_color] * size for _ in range(size)]

    block = [[0] * size for _ in range(size)]
    for r in range(size):
        for c in range(size):
            if r == 0 or r == size-1 or c == 0 or c == size-1:
                block[r][c] = border_color
            else:
                block[r][c] = fill_color
    return block

