# Find positions of each colored block
def find_blocks(grid):
    blocks = {'7': [], '9': [], '4': []}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            v = grid[r][c]
            if v in blocks:
                if not blocks[v]:  # start new block
                    blocks[v] = [(r, c)]
                else:
                    # Check if adjacent
                    if (r, c) == (blocks[v][-1][0]+1, blocks[v][-1][1]):
                        blocks[v].append((r, c))
                    elif (r, c) == (blocks[v][-1][0], blocks[v][-1][1]+1):
                        blocks[v].append((r, c))
                    elif (r, c) == (blocks[v][-1][0]-1, blocks[v][-1][1]):
                        blocks[v].append((r, c))
                    elif (r, c) == (blocks[v][-1][0], blocks[v][-1][1]-1):
                        blocks[v].append((r, c))
    return blocks

