# Simpler approach - find min/max row/col for each color

def find_blocks_simple(grid):
    blocks = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            v = grid[r][c]
            if v not in blocks:
                blocks[v] = {'rows': [r], 'cols': [c]}

    for v in blocks:
        blocks[v]['min_row'] = min(blocks[v]['rows'])
        blocks[v]['max_row'] = max(blocks[v]['rows'])
        blocks[v]['min_col'] = min(blocks[v]['cols'])
        blocks[v]['max_col'] = max(blocks[v]['cols'])
        blocks[v]['height'] = blocks[v]['max_row'] - blocks[v]['min_row'] + 1
        blocks[v]['width'] = blocks[v]['max_col'] - blocks[v]['min_col'] + 1

    return blocks

